/* --------------------------------------------------------------------------
 * Rhino icon sizing foundation
 * Source PBI: B-011
 * -------------------------------------------------------------------------- */

.rhino-icon-wrapper {
    align-items: center;
    color: currentColor;
    display: inline-flex;
    flex: 0 0 auto;
    justify-content: center;
    line-height: 0;
    vertical-align: middle;
}

.rhino-icon {
    color: currentColor;
    display: inline-block;
    fill: none;
    flex: 0 0 auto;
    height: 2.4rem;
    stroke: currentColor;
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 1.75;
    vertical-align: middle;
    width: 2.4rem;
}

.rhino-icon-wrapper--default .rhino-icon {
    height: 2.4rem;
    width: 2.4rem;
}

.rhino-icon-wrapper--compact .rhino-icon,
.rhino-icon--compact {
    height: 1.6rem;
    width: 1.6rem;
}

.rhino-icon-wrapper--small .rhino-icon,
.rhino-icon--small {
    height: 2rem;
    width: 2rem;
}

.rhino-icon-wrapper--large .rhino-icon,
.rhino-icon--large {
    height: 3.2rem;
    width: 3.2rem;
}

.rhino-icon--filled {
    fill: currentColor;
    stroke: none;
}

@media screen and (max-width: 749px) {
    .rhino-trust-marker {
        gap: var(--rhino-space-2);
    }

    .rhino-family-identifier {
        max-width: 100%;
    }
}

@media (forced-colors: active) {
    .rhino-badge,
    .rhino-family-identifier,
    .rhino-trust-list {
        forced-color-adjust: auto;
    }
}

/* --------------------------------------------------------------------------
 * Motion and loading
 * Source PBI: B-020
 * -------------------------------------------------------------------------- */

.rhino-transition {
    transition-duration: var(--rhino-motion-duration-fast);
    transition-property:
            background-color,
            border-color,
            color,
            opacity,
            transform;
    transition-timing-function: var(--rhino-motion-easing-standard);
}

.rhino-transition--overlay {
    transition-duration: var(--rhino-motion-duration-standard);
}

.rhino-fade-enter {
    opacity: 0;
}

.rhino-fade-enter.is-visible {
    opacity: 1;
}

.rhino-busy-region {
    min-height: 1px;
    position: relative;
}

.rhino-busy-region[aria-busy="true"] {
    cursor: progress;
}

.rhino-loading {
    align-items: center;
    color: var(--rhino-color-text-muted);
    display: inline-flex;
    font-size: var(--rhino-font-size-compact);
    gap: var(--rhino-space-2);
    line-height: var(--rhino-type-compact-line-height);
}

.rhino-spinner {
    animation: rhino-spinner-rotate 800ms linear infinite;
    border:
            0.2rem
            solid
            var(--rhino-color-alloy);
    border-block-start-color: var(--rhino-color-red-700);
    border-radius: var(--rhino-radius-round);
    display: inline-block;
    height: 2rem;
    width: 2rem;
}

.rhino-spinner--small {
    border-width: 0.15rem;
    height: 1.6rem;
    width: 1.6rem;
}

.rhino-skeleton {
    background: var(--rhino-color-mist);
    border-radius: var(--rhino-radius-control);
    display: block;
    min-height: 1.6rem;
}

.rhino-skeleton--text {
    max-width: 32rem;
    width: 100%;
}

.rhino-skeleton--short {
    max-width: 16rem;
}

.rhino-skeleton--media {
    aspect-ratio: 4 / 3;
    min-height: 0;
    width: 100%;
}

@keyframes rhino-spinner-rotate {
    to {
        transform: rotate(360deg);
    }
}

/* --------------------------------------------------------------------------
 * Technical diagrams
 * Source PBI: B-013
