.rhino-diagram {
    background: var(--rhino-color-white);
    border: var(--rhino-border-standard);
    border-radius: var(--rhino-radius-media);
    color: var(--rhino-color-text);
    margin: 0;
    overflow: hidden;
}

.rhino-diagram__canvas {
    background: var(--rhino-color-mist);
    overflow-x: auto;
    padding: var(--rhino-space-4);
}

.rhino-diagram__canvas svg {
    display: block;
    height: auto;
    margin-inline: auto;
    max-width: 100%;
}

.rhino-diagram__caption {
    border-block-start: var(--rhino-border-standard);
    padding: var(--rhino-space-4);
}

.rhino-diagram__caption > *:first-child {
    margin-block-start: 0;
}

.rhino-diagram__caption > *:last-child {
    margin-block-end: 0;
}

.rhino-diagram__title {
    font-size: var(--rhino-font-size-body);
    font-weight: var(--rhino-font-weight-semibold);
    line-height: 1.5;
    margin: 0;
}

.rhino-diagram__description {
    color: var(--rhino-color-text-muted);
    font-size: var(--rhino-font-size-compact);
    line-height: var(--rhino-type-compact-line-height);
    margin:
            var(--rhino-space-2)
            0
            0;
}

.rhino-diagram__legend {
    display: grid;
    gap: var(--rhino-space-2);
    list-style: none;
    margin:
            var(--rhino-space-4)
            0
            0;
    padding: 0;
}

.rhino-diagram__legend-item {
    align-items: start;
    display: grid;
    font-size: var(--rhino-font-size-compact);
    gap: var(--rhino-space-2);
    grid-template-columns: 2.8rem minmax(0, 1fr);
    line-height: var(--rhino-type-compact-line-height);
}

.rhino-diagram__callout-number {
    align-items: center;
    background: var(--rhino-color-red-700);
    border-radius: var(--rhino-radius-round);
    color: var(--rhino-color-white);
    display: inline-flex;
    font-size: var(--rhino-font-size-xs);
    font-variant-numeric: tabular-nums;
    font-weight: var(--rhino-font-weight-bold);
    height: 2.4rem;
    justify-content: center;
    width: 2.4rem;
}

.rhino-diagram-line {
    fill: none;
    stroke: var(--rhino-color-graphite);
    stroke-linecap: round;
    stroke-linejoin: round;
    stroke-width: 2;
}

.rhino-diagram-line--secondary {
    stroke: var(--rhino-color-steel);
    stroke-width: 1.5;
}

.rhino-diagram-line--callout {
    stroke: var(--rhino-color-red-700);
}

.rhino-diagram-line--water {
    stroke: var(--rhino-color-info);
    stroke-dasharray: 6 4;
}

.rhino-diagram-line--dimension {
    stroke: var(--rhino-color-graphite);
    stroke-width: 1.25;
}

.rhino-diagram-line--warning {
    stroke: var(--rhino-color-warning);
}

.rhino-diagram-label {
    fill: var(--rhino-color-carbon);
    font-family: var(--rhino-font-family-sans);
    font-size: 14px;
    font-weight: var(--rhino-font-weight-medium);
}

/* --------------------------------------------------------------------------
 * Restrained geological motif
